color_extra_css:
:root {
	--primary-hover: #3239C4;
	--primary-light: #EBEBFF;
	--secondary: #1A1A1A;
	--text: #1A1A1A;
	--text-muted: #7E7E7E;
	--border: #EDEDED;
	--surface: #FFFFFF;
	--white: #FFFFFF;
	--danger: #EF4444;
	--radius: 12px;
	--radius-lg: 16px;
	--radius-pill: 999px;
	--shadow: 0 4px 20px rgba(26, 26, 26, 0.06);
	--shadow-nav: 0 -4px 24px rgba(26, 26, 26, 0.08);
	--container: 1320px;
	--transition: 250ms ease;
	--font: 'Inter', system-ui, -apple-system, sans-serif;
	--sm-primary-soft: #EBEBFF;
	--sm-text: #1A1A1A;
	--sm-muted: #7E7E7E;
	--sm-border: #EDEDED;
	--sm-radius: 12px;
	--sm-radius-lg: 16px;
	--sm-shadow: var(--shadow);
	--sm-shadow-nav: var(--shadow-nav);
	--sm-surface: #FFFFFF;
}
body.sm-body {
	background-color: var(--sm-bg, #F8F9FA);
	font-family: 'Inter', system-ui, sans-serif;
}
